update public.countries set intro = coalesce(intro, 'Soups, stews and rice dishes from Yoruba, Igbo, Hausa and many other traditions.'), food_culture = coalesce(food_culture, 'Nigeria is home to hundreds of ethnic groups, and its food reflects that variety: pepper-rich stews, hearty soups eaten with swallows such as pounded yam or eba, grilled suya, and rice dishes shared at celebrations.'), is_featured = true where slug = 'nigeria';
