update public.countries set intro = coalesce(intro, 'Regional spice blends, dals, breads and sweets from across the subcontinent.'), food_culture = coalesce(food_culture, 'India''s cuisines vary widely by region, climate and community. Lentils, rice, wheat breads, vegetables and carefully balanced spice blends appear across the country, alongside a strong tradition of vegetarian cooking.'), is_featured = true where slug = 'india';
