update public.countries set intro = coalesce(intro, 'Tagines, couscous and mint tea, layered with warm spices.'), food_culture = coalesce(food_culture, 'Moroccan cooking blends Amazigh, Arab, Andalusian and other influences. Slow-cooked tagines, couscous, preserved lemons and warm spices such as cumin, ginger and cinnamon are typical, and mint tea is a daily ritual of hospitality.'), is_featured = true where slug = 'morocco';
